dataTransform.transform:
(

$q:= $query({"statement":"query($w:IntegrationMessageWhereInput){m:integrationMessage(where:$w,first:1,orderBy:{field:createdAt, direction:desc}){edges{node{message createdAt type{name color}}}}}","variables":{
  "w": {
    "global": {
      "_eq": true
    },
    "integrationId": {
      "_eq": "NetSuite"
    }
  }
}});
edges.node~>|$|{
  "message":$q.m.edges.node.message,
  "time": $q.m.edges.node.createdAt,
  "color": $not(data.active) ? "#cccccc" : $q.m.edges.node.type.color
}|

)

action.query:
query Query($where: IntegrationTransactionWhereInput, $orderBy: [IntegrationTransactionOrderByInput!], $first: Int, $after: String) {
  integrationTransaction(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        outbound
        externalId
        completeAt
        occurAt
        metadata
        request
        response
        status {
          id
          name
        }
        model {
          id
          name
        }
      }
    }
  }
}
